    "      case RectangularZone((cx, cy), width, height) =>",
    "        Point2D(cx + ((width / 2.0) * positiveNegativeRandom()), cy + ((height / 2.0) * positiveNegativeRandom()))",
    "    }",
    "",
    "    private def positiveNegativeRandom(): Double = {",
    "      val sign = if (nextRandom() < 0.5) 1 else -1",
    "      sign * nextRandom()",
    "    }",
    "  }",
    "}",
